internal class BrandVector(val heightFactor: Float, internal val data: String) {
    val path: Path by lazy { checkNotNull(PathParser.createPathFromPathData(data)) }
    val bounds: RectF by lazy { RectF().also { path.computeBounds(it, true) } }
}

